51. const game = new Phaser.Game(config);
52. const semanticInput = new SemanticInputRuntime(game);
53. semanticInput.start();
54. let disposeDesktopListener: (() => void) | undefined;
55. const formatRendererError = (value: unknown): string => {
56.   if (value instanceof Error) return value.stack ?? value.message;
57.   return String(value);
58. };
59. const handleRendererError = (event: ErrorEvent): void => {
60.   window.desktop?.reportError(
61.     `Unhandled error: ${formatRendererError(event.error ?? event.message)}`,
62.   );
63. };
64. const handleRendererRejection = (event: PromiseRejectionEvent): void => {
65.   window.desktop?.reportError(
66.     `Unhandled rejection: ${formatRendererError(event.reason)}`,
67.   );
68. };
69. window.addEventListener("error", handleRendererError);
70. window.addEventListener("unhandledrejection", handleRendererRejection);
71. window.addEventListener("beforeunload", () => {
72.   window.removeEventListener("error", handleRendererError);
73.   window.removeEventListener("unhandledrejection", handleRendererRejection);
74.   disposeDesktopListener?.();
75.   semanticInput.destroy();
76. }, { once: true });
77. 
78. const controlsToggle = document.getElementById(
79.   "controls-toggle",
80. ) as HTMLButtonElement | null;
81. const controlsPanel = document.getElementById("controls-panel");
82. controlsToggle?.addEventListener("click", () => {
83.   controlsPanel?.classList.toggle("collapsed");
84.   const collapsed = controlsPanel?.classList.contains("collapsed") ?? true;
85.   controlsToggle.textContent = collapsed ? "?" : "? Controls";
86.   controlsToggle.setAttribute("aria-expanded", String(!collapsed));
87.   controlsToggle.setAttribute(
88.     "title",
89.     collapsed ? "Show keyboard controls" : "Hide keyboard controls",
90.   );
91. });
92. 
93. const desktopFullscreen = document.getElementById(
94.   "desktop-fullscreen",
95. ) as HTMLButtonElement | null;
96. if (window.desktop && desktopFullscreen) {
97.   desktopFullscreen.style.display = "block";
98.   const updateFullscreenLabel = (isFullscreen: boolean): void => {
99.     desktopFullscreen.textContent = isFullscreen
100.       ? "Windowed (F11)"
101.       : "Fullscreen (F11)";
102.     desktopFullscreen.setAttribute("aria-pressed", String(isFullscreen));
103.   };
104.   window.desktop.getState()
105.     .then((state) => updateFullscreenLabel(state.isFullscreen))
106.     .catch((error: unknown) => {
107.       desktopFullscreen.disabled = true;
108.       desktopFullscreen.title = "Fullscreen control unavailable";
109.       debugLog("[desktop] Failed to read window state", error);
110.     });
111.   const toggleFullscreen = (): void => {
112.     window.desktop?.toggleFullscreen()
113.       .then(updateFullscreenLabel)
114.       .catch((error: unknown) => {
115.         debugLog("[desktop] Failed to toggle fullscreen", error);
116.       });
117.   };
118.   const handleFullscreenShortcut = (event: KeyboardEvent): void => {
119.     if (event.key !== "F11") return;
120.     event.preventDefault();
121.     toggleFullscreen();
122.   };
123.   desktopFullscreen.addEventListener("click", toggleFullscreen);
124.   document.addEventListener("keydown", handleFullscreenShortcut);
125.   const disposeFullscreenChange = window.desktop.onFullscreenChanged(
126.     updateFullscreenLabel,
127.   );
128.   disposeDesktopListener = () => {
129.     disposeFullscreenChange();
130.     desktopFullscreen.removeEventListener("click", toggleFullscreen);
131.     document.removeEventListener("keydown", handleFullscreenShortcut);
132.   };
133. }
