135. // Wire up the HTML debug toggle (local dev only)
136. const debugToggle = document.getElementById("debug-toggle") as HTMLElement | null;
137. const checkbox = document.getElementById("debug-checkbox") as HTMLInputElement | null;
138. const label = document.getElementById("debug-label") as HTMLElement | null;
139. const panel = document.getElementById("debug-panel") as HTMLElement | null;
140. 
141. const debugCheatsSection = document.getElementById("debug-cheats") as HTMLElement | null;
142. 
143. if (!isLocalDev()) {
144.   // Hide all debug UI on production (github.io)
145.   if (debugToggle) debugToggle.style.display = "none";
146.   if (panel) panel.style.display = "none";
147. } else {
148.   if (checkbox) {
149.     checkbox.checked = isDebug();
150.     // Blur on change so that pressing SPACE to start the game doesn't
151.     // accidentally toggle the checkbox off.
152.     checkbox.addEventListener("change", () => {
153.       const on = toggleDebug();
154.       checkbox.checked = on;
155.       checkbox.blur();
156.       if (label) label.style.color = on ? "#00ff00" : "#555";
157.       if (panel) panel.style.display = on ? "block" : "none";
158.       if (debugCheatsSection) debugCheatsSection.style.display = on ? "block" : "none";
159.     });
160.     onDebugChanged((on) => {
161.       checkbox.checked = on;
162.       if (label) label.style.color = on ? "#00ff00" : "#555";
163.       if (panel) panel.style.display = on ? "block" : "none";
164.       if (debugCheatsSection) debugCheatsSection.style.display = on ? "block" : "none";
165.     });
166.     // Sync initial state in case debug was already on
167.     if (isDebug()) {
168.       if (label) label.style.color = "#00ff00";
169.       if (panel) panel.style.display = "block";
170.       if (debugCheatsSection) debugCheatsSection.style.display = "block";
171.     }
172.   }
173. 
174.   // Initialize debug command textbox
175.   initDebugCommandInput();
176. }
