178. // Clicking on the game canvas should blur the debug command input
179. // so that Phaser regains keyboard focus
180. const gameContainer = document.getElementById("game-container");
181. const debugCmd = document.getElementById("debug-cmd") as HTMLInputElement | null;
182. if (gameContainer && debugCmd) {
183.   gameContainer.addEventListener("pointerdown", () => {
184.     if (document.activeElement === debugCmd) {
185.       debugCmd.blur();
186.     }
187.   });
188. }
