76.   const target = parseUrl(value);
77.   if (!target || !hasSafeCredentials(target)) return false;
78.   if (target.protocol === `${DESKTOP_APP_SCHEME}:`) {
79.     return target.hostname === DESKTOP_APP_HOST;
