17.     server.once("error", rejectListen);
18.     server.listen(0, "127.0.0.1", resolveListen);
19.   });
20.   const address = server.address();
21.   if (!address || typeof address === "string") {
22.     server.close();
23.     throw new Error("Unable to allocate a desktop development port");
24.   }
25.   const { port } = address;
26.   await new Promise((resolveClose, rejectClose) => {
27.     server.close((error) => {
28.       if (error) rejectClose(error);
29.       else resolveClose();
30.     });
31.   });
32.   return port;
33. }
