39.       throw new Error(`Vite exited before Electron started (${child.exitCode})`);
40.     }
41.     try {
42.       const response = await fetch(url);
43.       if (response.ok) return;
44.     } catch {
45.       // Vite is still starting.
46.     }
47.     await new Promise((resolveDelay) => setTimeout(resolveDelay, 150));
48.   }
49.   throw new Error(`Timed out waiting for Vite at ${url}`);
50. }
