import { chromium } from '@playwright/test';
import { writeFile } from 'node:fs/promises';

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (error) => errors.push(error.message));
page.on('console', (message) => {
  if (message.type() === 'error') errors.push(message.text());
});

const clickGame = async (x, y) => {
  const canvas = page.locator('#game-container canvas');
  await canvas.waitFor({ state: 'visible' });
  const bounds = await canvas.boundingBox();
  if (!bounds) throw new Error('Game canvas has no bounds');
  await page.mouse.click(bounds.x + (x / 640) * bounds.width, bounds.y + (y / 528) * bounds.height);
};
const holdKey = async (key, duration = 180) => {
  await page.keyboard.down(key);
  await page.waitForTimeout(duration);
  await page.keyboard.up(key);
  await page.waitForTimeout(120);
};
const state = async () => page.locator('#debug-state').textContent() ?? '';
const waitForState = async (text) => page.locator('#debug-state').waitFor({ state: 'attached' }).then(async () => {
  const deadline = Date.now() + 30000;
  while (Date.now() < deadline) {
    if ((await state()).includes(text)) return;
    await page.waitForTimeout(100);
  }
  throw new Error(`Timed out waiting for ${text}: ${await state()}`);
});
const submitDebug = async (command) => {
  const input = page.locator('#debug-cmd');
  await input.fill(command);
  await input.press('Enter');
  await input.blur();
};
const drainCutscenes = async (destination = 'OVERWORLD') => {
  for (let attempt = 0; attempt < 40; attempt += 1) {
    const current = await state();
    if (current.includes(destination)) return;
    if (current.includes('CUTSCENE')) {
      await page.waitForTimeout(380);
      await holdKey('Escape');
    } else {
      await page.waitForTimeout(120);
    }
  }
  throw new Error(`Timed out draining cutscenes: ${await state()}`);
};
const saveCanvas = async (name) => {
  await page.waitForTimeout(250);
  const base64 = await page.locator('#game-container canvas').evaluate((canvas) => {
    return canvas.toDataURL('image/png').split(',')[1];
  });
  if (!base64) throw new Error(`No PNG data for ${name}`);
  await writeFile(`public/screenshots/${name}`, Buffer.from(base64, 'base64'));
};

try {
  await page.addInitScript(() => {
    let seed = 0x2d0d2026;
    Math.random = () => {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      return seed / 0x100000000;
    };
    localStorage.clear();
    localStorage.setItem('2dnd_preferences', JSON.stringify({
      version: 2,
      audio: {
        masterVolume: 0,
        musicVolume: 0,
        sfxVolume: 0,
        dialogVolume: 0,
        muted: true,
      },
      accessibility: {
        reducedMotion: true,
        textScale: 1,
        highContrast: false,
        advanceMode: 'manual',
      },
    }));
  });
  await page.goto('http://127.0.0.1:4317/game.html', { waitUntil: 'networkidle' });
  await waitForState('BOOT | Screen: title');
  await clickGame(320, 324);
  await waitForState('BOOT | Screen: character');
  await clickGame(284, 160);
  await holdKey('Enter');
  await waitForState('BOOT | Screen: stats');
  await clickGame(390, 64);
  await clickGame(400, 460);
  await waitForState('BOOT | Screen: appearance');
  await clickGame(320, 112);
  await clickGame(420, 312);
  await drainCutscenes();
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const current = await state();
    if (!current.includes('[TUTORIAL]') && !current.includes('[MENU]')) break;
    await holdKey('Escape');
  }
  await saveCanvas('showcase-overworld.png');

  const checkbox = page.locator('#debug-checkbox');
  if (!(await checkbox.isChecked())) await checkbox.check();
  await submitDebug('/tp Willowdale');
  for (let attempt = 0; attempt < 6; attempt += 1) {
    await holdKey('Space', 260);
    if ((await state()).includes('[CITY:willowdale_city:0]')) break;
  }
  await waitForState('[CITY:willowdale_city:0]');
  await saveCanvas('showcase-city.png');

  await submitDebug('/battleview goblinRaidingParty forest dusk clear');
  for (let attempt = 0; attempt < 40; attempt += 1) {
    const current = await state();
    if (current.includes('BATTLE')) break;
    if (current.includes('CUTSCENE')) {
      await page.waitForTimeout(380);
      await holdKey('Escape');
    } else {
      await page.waitForTimeout(120);
    }
  }
  await waitForState('BATTLE');
  await saveCanvas('showcase-battle.png');

  if (errors.length > 0) throw new Error(`Browser errors: ${errors.join(' | ')}`);
  process.stdout.write('Captured overworld, city, and battle screenshots.\n');
} finally {
  await browser.close();
}
